async function probujDoSkutku(fn, maxProb) {
  let ostatniBlad;
  for (let proba = 1; proba <= maxProb; proba++) {
    try {
      return await fn();
    } catch (err) {
      ostatniBlad = err;
    }
  }
  throw ostatniBlad;
}
