function stylemCallback(wartosc, callback) {
  setTimeout(() => callback(null, wartosc * 2), 100);
}
function opromisuj(wartosc) {
  return new Promise((resolve, reject) => {
    stylemCallback(wartosc, (blad, wynik) => {
      if (blad) reject(blad);
      else resolve(wynik);
    });
  });
}
async function main() {
  const wynik = await opromisuj(21);
  console.log(wynik);
}
main(); // 42

